// js
const rate = get(ctx.entry, 'terms.rate', {});
const unit = get(rate, 'unit', null);
const amount = Number(get(rate, 'amount', 0));
const employer = get(ctx.subject, 'employer', {});
const region = get(employer, 'entity_extension_data.region', null);
const table = ctx.lookup.by_region ?? {};
if (region == null || table[region] == null) return true;
const hours = Number(
	get(ctx.entry, 'terms.normal_hours_per_day', ctx.lookup.normal_hours_per_day),
);
const daily =
	unit === 'DAILY'
		? amount
		: unit === 'MONTHLY'
			? amount / ctx.lookup.wage_divisor
			: amount * hours;
return daily >= Number(table[region]);

