validate:
// Labour Protection Act B.E. 2541 s. 90: a certified worker's day wage must reach the
// skill-standard rate of the trade. The rate is a recorded term fact, not a table here.
const rate = get(ctx.entry, 'terms.rate', null);
const amount = get(rate, 'amount', 0);
const unit = get(rate, 'unit', null);
const daily =
	unit === 'DAILY'
		? amount
		: unit === 'MONTHLY'
			? amount / ctx.lookup.wage_divisor
			: amount * get(ctx.entry, 'terms.normal_hours_per_day', ctx.lookup.normal_hours_per_day);
return daily >= get(ctx.entry, 'employee_extension_data.term_facts.skill_standard_day_rate', 0);

// Labour Protection Act B.E. 2541 s. 27: planned overtime beyond five continuous hours
// needs a recorded rest break. The rest of the day is checked on actual work.
const planned = get(ctx.entry, 'planned_overtime_intervals', []);
if (planned.length !== 1) return true;
const row = first(planned);
const end = get(row, 'end', null);
if (end == null) return true;
if (elapsed_minutes(get(row, 'start', null), end) <= ctx.lookup.elapsed_minutes) return true;
return interval_minutes(get(row, 'breaks', [])) >= ctx.lookup.break_minutes;

// The contract's engagement is the model's declared enum; this rule checks the
// jurisdiction's work classification and tax-residency categories.
const categories = ctx.lookup.categories;
const work = get(ctx.entry, 'terms.statutory_work_category', null);
if (work != null && !categories.statutory_work_category.includes(work)) return false;
const residency = get(ctx.entry, 'terms.residency_status', null);
if (residency != null && !categories.residency_status.includes(residency)) return false;
return true;

// The agreed rate and normal working time must meet this version's contract limits.
// Hazardous work is seven hours a day and forty-two a week (LPA ss. 23, 68-69).
const limits = ctx.lookup.limits;
const terms = get(ctx.entry, 'terms', {});
const rate = get(terms, 'rate', null);
if (rate != null && get(rate, 'amount', 0) < 0) return false;
const hazardous = get(terms, 'statutory_work_category', null) === 'HAZARDOUS';
const maxDay = hazardous
	? limits.normal_hours_per_day_hazardous_maximum
	: limits.normal_hours_per_day_maximum;
const maxWeek = hazardous
	? limits.normal_hours_per_week_hazardous_maximum
	: limits.normal_hours_per_week_maximum;
const day = get(terms, 'normal_hours_per_day', null);
if (day != null && day <= limits.normal_hours_per_day_minimum) return false;
if (day != null && day > maxDay) return false;
const week = get(terms, 'normal_hours_per_week', null);
if (week != null && week <= limits.normal_hours_per_week_minimum) return false;
if (week != null && week > maxWeek) return false;
return true;

// The recorded PVD election and overtime category must meet this version's contract terms.
const data = get(ctx.entry, 'employee_extension_data', {});
const pvd = get(get(get(data, 'facts', {}), 'statutory', {}), 'PVD', {});
const percent = get(get(pvd, 'elections', {}), 'employee_percent', null);
const member = get(pvd, 'kind', '') === 'MEMBER';
if (member && typeof percent !== 'number') return false;
if (member && percent < ctx.lookup.pvd_minimum_percent) return false;
if (member && percent > ctx.lookup.pvd_maximum_percent) return false;
const overtime = get(get(data, 'term_facts', {}), 'overtime_category', null);
return overtime === null || ctx.lookup.overtime_categories.includes(overtime);

// The employer's province and WCF business code are the keys the payroll formulas read.
const entity = get(ctx.entry, 'entity_extension_data', {});
const region = get(entity, 'region', null);
const risk = get(entity, 'risk_class', null);
if (region !== null && typeof region !== 'string') return false;
if (region === '') return false;
if (risk === null) return true;
if (typeof risk !== 'string') return false;
if (risk.length !== ctx.lookup.risk_class_digits) return false;
const digits = '0123456789';
return risk.split('').every((c) => digits.includes(c));

// A deduction consent's ordered interval begins on or after its receipt and ends after it starts.
const inputs = get(ctx.entry, 'inputs', {});
const opened = get(ctx.entry, 'opened_on', null);
const from = get(inputs, 'effective_from', null);
const to = get(inputs, 'effective_to', null);
if (opened == null || from == null || to == null) return false;
return from >= opened && to >= from;

// A signed consent needs its actual prior signature date and the signed source document.
const inputs = get(ctx.entry, 'inputs', {});
const opened = get(ctx.entry, 'opened_on', null);
const signed = get(inputs, 'signed_on', null);
if (opened == null || signed == null) return false;
return signed <= opened && get(ctx.entry, 'evidence_file', null) != null;

// Each authorised deduction code occurs once with its actual amount and currency limit.
const inputs = get(ctx.entry, 'inputs', {});
const deductions = get(inputs, 'deductions', null);
if (!Array.isArray(deductions) || deductions.length === 0) return false;
return !deductions.some(
	(row, index) =>
		deductions.some(
			(other, earlier) => earlier < index && get(other, 'code', null) === get(row, 'code', null)
		)
);
